#include <bits/stdc++.h>
using namespace std;
class Solution {static bool coprime(int a,int b){while(b){int t=a%b;a=b;b=t;}return a==1;}public:int distinctSequences(int n){const int M=1000000007;int dp[7][7]={};for(int a=1;a<=6;++a)dp[0][a]=1;for(int len=2;len<=n;++len){int nd[7][7]={};for(int a=0;a<=6;++a)for(int b=1;b<=6;++b)if(dp[a][b])for(int c=1;c<=6;++c)if(c!=a&&c!=b&&coprime(b,c)){nd[b][c]=(nd[b][c]+dp[a][b])%M;}memcpy(dp,nd,sizeof(dp));}long long ans=0;for(int a=0;a<=6;++a)for(int b=1;b<=6;++b)ans+=dp[a][b];return ans%M;}};
